package com.johnny.hotel.workforce;
import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.organization.Department;import com.johnny.hotel.pagination.*;import com.johnny.hotel.workforce.WorkforceModels.*;import lombok.RequiredArgsConstructor;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class AttendanceService {
 private final WorkforceMapper mapper;private final WorkforceAccess access;private final WorkforceApprovalRouting routing;private final WorkforceTaskService workflows;private final SysAuditLogMapper audits;private final PaginationSupport pagination;private final WorkforceProperties properties;private final Clock clock;
 private LocalDateTime now(){return LocalDateTime.now(clock);}
 private void need(boolean ok,String message){if(!ok)throw new BusinessException(409,message);}
 private String required(String value,String name,int max){if(value==null||value.isBlank())throw new BusinessException(name+" is required");String v=value.trim();if(v.length()>max)throw new BusinessException(name+" is too long");return v;}
 private void audit(Long actor,Long target,String action,String detail){need(audits.insert(SysAuditLog.builder().operatorId(actor).targetUserId(target).action(action).detail(detail).build())==1,"Audit write failed");}
 @Transactional(isolation=Isolation.READ_COMMITTED) public AttendanceSession checkIn(String key,String ip,String userAgent){var a=access.actor();need(!a.has("OWNER"),"ATTENDANCE_EXEMPT: OWNER accounts do not participate in employee attendance");key=required(key,"request key",100);var prior=mapper.punchByKey(a.id(),key);if(prior!=null){need(prior.getPunchType()==0,"Request key belongs to another punch");return session(prior.getSessionId());}mapper.lockUser(a.id());need(mapper.openForUpdate(a.id())==null,"Employee already has an open attendance");var at=now();var s=AttendanceSession.builder().employeeId(a.id()).status(0).effectiveCheckIn(at).build();try{need(mapper.insertSession(s)==1,"Attendance session creation failed");var p=AttendancePunch.builder().employeeId(a.id()).sessionId(s.getId()).punchType(0).punchedAt(at).ipAddress(required(ip,"IP address",45)).source("WEB").userAgent(userAgent==null?null:userAgent.substring(0,Math.min(500,userAgent.length()))).operatorUserId(a.id()).requestKey(key).build();need(mapper.insertPunch(p)==1&&mapper.attachIn(s.getId(),p.getId())==1,"Attendance punch creation failed");audit(a.id(),a.id(),"ATTENDANCE_CHECK_IN","Session "+s.getId());return mapper.lockSession(s.getId());}catch(DuplicateKeyException e){throw new BusinessException(409,"Employee already has an open attendance or request was already processed");}}
 @Transactional(isolation=Isolation.READ_COMMITTED) public AttendanceSession checkOut(String key,String ip,String userAgent){var a=access.actor();need(!a.has("OWNER"),"ATTENDANCE_EXEMPT: OWNER accounts do not participate in employee attendance");key=required(key,"request key",100);var prior=mapper.punchByKey(a.id(),key);if(prior!=null){need(prior.getPunchType()==1,"Request key belongs to another punch");return session(prior.getSessionId());}mapper.lockUser(a.id());var s=mapper.openForUpdate(a.id());need(s!=null,"Employee has no open attendance");var at=now();need(at.isAfter(s.getEffectiveCheckIn()),"Checkout must be after check-in");var p=AttendancePunch.builder().employeeId(a.id()).sessionId(s.getId()).punchType(1).punchedAt(at).ipAddress(required(ip,"IP address",45)).source("WEB").userAgent(userAgent==null?null:userAgent.substring(0,Math.min(500,userAgent.length()))).operatorUserId(a.id()).requestKey(key).build();try{need(mapper.insertPunch(p)==1&&mapper.closeSession(s.getId(),at,p.getId())==1,"Attendance checkout changed concurrently");}catch(DuplicateKeyException e){throw new BusinessException(409,"Attendance request was already processed");}audit(a.id(),a.id(),"ATTENDANCE_CHECK_OUT","Session "+s.getId());return mapper.lockSession(s.getId());}
 private AttendanceSession session(Long id){var s=mapper.lockSession(id);if(s==null)throw new BusinessException(404,"Attendance session not found");return s;}
 public AttendanceSession current(){var a=access.actor();var s=mapper.open(a.id());if(s!=null&&s.getEffectiveCheckIn().isBefore(now().minusHours(properties.getMissingCheckoutHours())))s.setExceptionCode("MISSING_CHECKOUT");return s;}
 public PageResult<AttendanceSession> mine(LocalDateTime from,LocalDateTime to,Integer page,Integer size){var a=access.actor();var w=pagination.window(page,size,true);var rows=pagination.limit(w)==0?List.<AttendanceSession>of():mapper.attendancePage(a.id(),from,to,w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.attendanceCount(a.id(),from,to));}
 public PageResult<AttendanceSession> query(Long employee,Long department,LocalDateTime from,LocalDateTime to,Integer page,Integer size){var a=access.actor();if(!a.any("HR_ADMIN","OWNER","SUPER_ADMIN")){need(a.departmentId()!=null,"Employee has no department");Department managed=mapper.lockDepartment(a.departmentId());if(managed==null||!Objects.equals(managed.getManagerUserId(),a.id()))throw access.denied();department=a.departmentId();}var w=pagination.window(page,size,true);var rows=pagination.limit(w)==0?List.<AttendanceSession>of():mapper.attendanceAdminPage(employee,department,from,to,now().minusHours(properties.getMissingCheckoutHours()),w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.attendanceAdminCount(employee,department,from,to));}
 public PageResult<AttendanceSession> anomalies(Integer page,Integer size){var a=access.actor();Long department=null;if(!a.any("HR_ADMIN","OWNER","SUPER_ADMIN")){need(a.departmentId()!=null,"Employee has no department");Department managed=mapper.lockDepartment(a.departmentId());if(managed==null||!Objects.equals(managed.getManagerUserId(),a.id()))throw access.denied();department=a.departmentId();}var w=pagination.window(page,size,true);LocalDateTime before=now().minusHours(properties.getMissingCheckoutHours());var rows=pagination.limit(w)==0?List.<AttendanceSession>of():mapper.anomalyPage(department,before,w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.anomalyCount(department,before));}
 @Transactional(isolation=Isolation.READ_COMMITTED) public AttendanceCorrection requestCorrection(WorkforceRequests.CorrectionCreate r){var a=access.actor();need(!a.has("OWNER"),"ATTENDANCE_EXEMPT: OWNER accounts do not participate in employee attendance");need(r!=null,"Request required");String key=required(r.getRequestKey(),"request key",100);var old=mapper.correctionByKey(a.id(),key);if(old!=null)return old;mapper.lockUser(a.id());var route=routing.resolve(a);routing.requireNotExempt(route,"ATTENDANCE");String type=required(r.getCorrectionType(),"correction type",32).toUpperCase(Locale.ROOT);need(Set.of("MISSING_CHECK_IN","MISSING_CHECK_OUT","ADJUST_CHECK_IN","ADJUST_CHECK_OUT").contains(type),"Unsupported correction type");AttendanceSession s=r.getSessionId()==null?null:mapper.lockSession(r.getSessionId());need(s==null||s.getEmployeeId().equals(a.id()),"Attendance session is not owned by employee");if(!type.equals("MISSING_CHECK_IN"))need(s!=null,"Attendance session is required");var c=AttendanceCorrection.builder().employeeId(a.id()).departmentIdSnapshot(route.departmentId()).approverUserIdSnapshot(route.approver()).approvalRoute(route.code()).sessionId(r.getSessionId()).correctionType(type).requestedCheckIn(r.getRequestedCheckIn()).requestedCheckOut(r.getRequestedCheckOut()).reason(required(r.getReason(),"reason",500)).requestKey(key).requestedAt(now()).status(0).build();need(mapper.insertCorrection(c)==1,"Correction request creation failed");Long task=workflows.create(8,"ATTENDANCE_CORRECTION:"+c.getId(),"Attendance correction "+c.getId(),c.getReason(),a.id(),route);need(mapper.attachCorrectionTask(c.getId(),task)==1,"Correction task link failed");audit(a.id(),a.id(),"APPROVAL_ROUTE_RESOLVED","Correction "+c.getId()+" route "+route.code());return mapper.lockCorrection(c.getId());}
 @Transactional(isolation=Isolation.READ_COMMITTED) public AttendanceCorrection decideCorrection(Long id,boolean approve,String note){var a=access.actor();var c=mapper.lockCorrection(id);if(c==null)throw new BusinessException(404,"Correction not found");if(c.getStatus()!=0)return c;if(!Objects.equals(c.getApproverUserIdSnapshot(),a.id())||c.getEmployeeId().equals(a.id()))throw access.denied();if(!approve)need(note!=null&&!note.isBlank(),"Rejection note is required");if(approve){AttendanceSession s=c.getSessionId()==null?null:mapper.lockSession(c.getSessionId());if(s==null){need(c.getRequestedCheckIn()!=null,"Requested check-in is required");s=AttendanceSession.builder().employeeId(c.getEmployeeId()).status(c.getRequestedCheckOut()==null?0:1).effectiveCheckIn(c.getRequestedCheckIn()).effectiveCheckOut(c.getRequestedCheckOut()).build();need(mapper.insertSession(s)==1,"Corrected attendance creation failed");}LocalDateTime in=c.getRequestedCheckIn()==null?s.getEffectiveCheckIn():c.getRequestedCheckIn(),out=c.getRequestedCheckOut()==null?s.getEffectiveCheckOut():c.getRequestedCheckOut();need(out==null||out.isAfter(in),"Effective checkout must be after check-in");need(mapper.insertCorrectionFact(CorrectionFact.builder().requestId(c.getId()).sessionId(s.getId()).effectiveCheckIn(in).effectiveCheckOut(out).approvedBy(a.id()).approvedAt(now()).build())==1,"Correction fact creation failed");need(mapper.applyCorrection(s.getId(),in,out)==1,"Corrected attendance update failed");}
  need(mapper.decideCorrection(id,approve?1:2,note,a.id(),now())==1,"Correction changed concurrently");workflows.finish(c.getTaskId(),a.id(),!approve,approve?"Correction approved":"Correction rejected");audit(a.id(),c.getEmployeeId(),approve?"ATTENDANCE_CORRECTION_APPROVED":"ATTENDANCE_CORRECTION_REJECTED","Correction "+id);return mapper.lockCorrection(id);}
 @Transactional public AttendanceCorrection claimCorrection(Long id){var a=access.actor();var c=mapper.lockCorrection(id);need(c!=null&&c.getStatus()==0&&c.getApproverUserIdSnapshot()==null,"Correction is not claimable");need(!c.getEmployeeId().equals(a.id()),"Self approval is forbidden");workflows.claim(c.getTaskId(),a);need(mapper.resolveCorrectionApprover(c.getTaskId(),a.id())==1,"Approver changed concurrently");audit(a.id(),c.getEmployeeId(),"ATTENDANCE_APPROVER_RESOLVED","Correction "+id);return mapper.lockCorrection(id);}
 @Transactional public AttendanceCorrection reassignCorrection(Long id,Long approver,String reason){var a=access.actor();access.system(a);var c=mapper.lockCorrection(id);need(c!=null&&c.getStatus()==0,"Correction is not pending");var requester=access.employee(c.getEmployeeId());var route=routing.resolve(requester);routing.requireNotExempt(route,"ATTENDANCE");need(!Objects.equals(c.getEmployeeId(),approver),"Self approval is forbidden");if(route.approver()!=null)need(Objects.equals(route.approver(),approver),"Recovery approver must match current routing");else need(route.eligibleRoles().stream().anyMatch(access.employee(approver).roles()::contains),"Recovery approver is not eligible for current routing");access.employee(approver);need(mapper.reassignCorrection(id,approver)==1,"Correction changed concurrently");workflows.reassign(c.getTaskId(),approver,a.id(),required(reason,"reassignment reason",500));audit(a.id(),c.getEmployeeId(),"ATTENDANCE_APPROVER_REROUTED","Correction "+id+" via "+route.code());return mapper.lockCorrection(id);}
 public PageResult<AttendanceCorrection> corrections(boolean pendingForMe,Integer status,Integer page,Integer size){var a=access.actor();var w=pagination.window(page,size,true);if(pendingForMe){var rows=pagination.limit(w)==0?List.<AttendanceCorrection>of():mapper.pendingCorrections(a.id(),w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.pendingCorrectionCount(a.id()));}var rows=pagination.limit(w)==0?List.<AttendanceCorrection>of():mapper.correctionPage(a.id(),null,status,w.offset(),pagination.limit(w));return pagination.result(w,rows,mapper.correctionCount(a.id(),null,status));}
}
